<header class="admin-header"><div><p class="eyebrow">Configuration</p><h1>Settings</h1></div></header><form class="panel settings-form" method="post" action="<?= e(url('admin/settings')) ?>"><?= csrf_field() ?><?php foreach(['site_name'=>'Site name','site_tagline'=>'Tagline','full_name'=>'Full name','professional_title'=>'Professional title','company'=>'Company','location'=>'Location','email'=>'Email','website'=>'Website','github'=>'GitHub','linkedin'=>'LinkedIn'] as $key=>$label):?><label><?= e($label) ?><input name="<?= e($key) ?>" value="<?= e((string)($values[$key]??'')) ?>"></label><?php endforeach?><label>Biography<textarea name="bio" rows="4"><?= e((string)($values['bio']??'')) ?></textarea></label><label>About page Markdown<textarea name="about_markdown" rows="16"><?= e((string)($values['about_markdown']??'')) ?></textarea></label><button class="button">Save settings</button></form>
